from pathlib import Path
p=Path('/mnt/data/nexora_work/client/src/main.jsx')
s=p.read_text()
# imports
s=s.replace('BarChart3}', 'BarChart3, UserRound, Wrench, Activity, Download, Eye, CreditCard, AlertTriangle, FileSpreadsheet}')
# helper after adminApi
needle='const adminApi=async(path,opts={})=>{const token=localStorage.getItem("adminToken");const r=await fetch(API+path,{...opts,headers:{"Content-Type":"application/json",...(token?{Authorization:`Bearer ${token}`}:{})}});const d=await r.json().catch(()=>({}));if(!r.ok)throw new Error(d.message||"Admin request failed");return d};'
helper=needle+'''\nconst downloadAdminCsv=async(type)=>{const token=localStorage.getItem("adminToken");const r=await fetch(API+`/admin/export/${type}`,{headers:{Authorization:`Bearer ${token}`}});if(!r.ok){const d=await r.json().catch(()=>({}));throw new Error(d.message||"Export failed")}const blob=await r.blob();const a=document.createElement("a");a.href=URL.createObjectURL(blob);a.download=`nexora-${type}.csv`;document.body.appendChild(a);a.click();a.remove();URL.revokeObjectURL(a.href)};'''
s=s.replace(needle,helper)
# AdminApp data/nav/load
s=s.replace('data,setData=useState({overview:null,users:[],transactions:[],withdrawals:[],packages:[]})','data,setData=useState({overview:null,users:[],transactions:[],withdrawals:[],packages:[]})')
s=s.replace('const nav=[["overview","Overview",BarChart3],["users","Users",UsersRound],["transactions","Transactions",ReceiptText],["withdrawals","Withdrawals",HandCoins],["packages","Packages",PackageIcon]];', 'const nav=[["overview","Overview",BarChart3],["users","Users",UsersRound],["transactions","Transactions",ReceiptText],["repair","Payment repair",Wrench],["withdrawals","Withdrawals",HandCoins],["packages","Packages",PackageIcon],["activity","Activity log",Activity]];')
s=s.replace('{page==="transactions"&&<AdminTransactions rows={data.transactions}/>} {page==="withdrawals"', '{page==="transactions"&&<AdminTransactions rows={data.transactions}/>} {page==="repair"&&<AdminPaymentRepair action={action}/>} {page==="withdrawals"')
s=s.replace('{page==="packages"&&<AdminPackages rows={data.packages} action={action}/>}</main>', '{page==="packages"&&<AdminPackages rows={data.packages} action={action}/>} {page==="activity"&&<AdminActivity/>}</main>')
# replace AdminOverview function
start=s.index('function AdminOverview('); end=s.index('function AdminUsers(',start)
over='''function AdminOverview({data,onRefresh}){if(!data)return <div className="adminloading">Loading overview…</div>;const cards=[["Total users",data.users,UsersRound],["Active users",data.activeUsers,UserCheck],["Transactions",data.transactions,ReceiptText],["Pending payments",data.pendingPayments,Clock3],["Failed payments",data.failedPayments||0,AlertTriangle],["Successful package sales",money(data.successfulPayments),CheckCircle2],["Pending withdrawals",data.pendingWithdrawals,HandCoins],["Total commissions",money(data.totalCommissions),ArrowUpRight]];return <section className="adminsection"><div className="adminsectionhead"><div><span className="pill">CONTROL CENTER</span><h1>Good to see you, Administrator</h1><p className="muted">Monitor NEXORA activity, repair verified payments and manage member operations.</p></div><button className="secondary" onClick={onRefresh}><RefreshCw size={16}/> Refresh</button></div><div className="adminstats">{cards.map(([label,value,I])=><div className="adminstat" key={label}><I size={19}/><span>{label}</span><strong>{value}</strong></div>)}</div>{((data.pendingPayments||0)>0||(data.pendingWithdrawals||0)>0||(data.failedPayments||0)>0)&&<div className="adminpanel alertpanel"><div><h3><AlertTriangle size={18}/> Attention needed</h3><p className="muted">{data.pendingPayments||0} pending payment(s), {data.pendingWithdrawals||0} pending withdrawal(s), and {data.failedPayments||0} failed payment(s) are currently recorded.</p></div><div className="adminquick"><span>{data.pendingPayments||0} Pending payments</span><span>{data.pendingWithdrawals||0} Pending withdrawals</span><span>{data.failedPayments||0} Failed payments</span></div></div>}<div className="adminpanel"><div><h3>Admin access</h3><p className="muted">Admin sessions expire after 12 hours. Sensitive actions are recorded in the Activity Log.</p></div><div className="adminquick"><span><Check size={14}/> Users</span><span><Check size={14}/> Payments</span><span><Check size={14}/> Withdrawals</span><span><Check size={14}/> Audit log</span></div></div><div className="adminpanel"><div><h3>Data exports</h3><p className="muted">Download current member, transaction or withdrawal records as CSV.</p></div><div className="adminquick"><button className="rowaction" onClick={()=>downloadAdminCsv("users")}><Download size={14}/> Users CSV</button><button className="rowaction" onClick={()=>downloadAdminCsv("transactions")}><Download size={14}/> Transactions CSV</button><button className="rowaction" onClick={()=>downloadAdminCsv("withdrawals")}><Download size={14}/> Withdrawals CSV</button></div></div><div className="adminpanel warningpanel"><div><h3>Paystack environment</h3><p className="muted">Current server key mode: <strong>{data.paystackMode}</strong>. Live mode is required for real M-Pesa transactions.</p></div><a className="secondary" href="https://dashboard.paystack.com/" target="_blank" rel="noreferrer">Open Paystack</a></div></section>}\n'''
s=s[:start]+over+s[end:]
# replace AdminUsers through before AdminTransactions
start=s.index('function AdminUsers('); end=s.index('function AdminTransactions(',start)
users='''function AdminUsers({rows,search,setSearch,action}){\n const [balanceOpen,setBalanceOpen]=useState(false),[detail,setDetail]=useState(null),[detailsLoading,setDetailsLoading]=useState(false);\n const [form,setForm]=useState({email:"",mode:"add",amount:"",reason:"",updateTotalEarned:false});\n const filtered=rows.filter(u=>!search||`${u.name} ${u.email} ${u.phone} ${u.referralCode}`.toLowerCase().includes(search.toLowerCase()));\n const openBalance=(u=null)=>{const preset=u?.email || (search.includes("@") ? search : "");setForm({email:preset,mode:"add",amount:"",reason:"",updateTotalEarned:false});setBalanceOpen(true)};\n const openDetails=async u=>{setDetailsLoading(true);try{setDetail(await adminApi(`/admin/users/${u.id}/details`))}catch(e){alert(e.message)}finally{setDetailsLoading(false)}};\n const submit=async e=>{e.preventDefault();const ok=await action(()=>adminApi("/admin/users/balance",{method:"POST",body:JSON.stringify({...form,amount:Number(form.amount)})}),"Member balance corrected successfully");if(ok){setBalanceOpen(false);setForm({email:"",mode:"add",amount:"",reason:"",updateTotalEarned:false})}};\n return <section className="adminsection">\n  <div className="adminsectionhead"><div><h1>Users</h1><p className="muted">Search members, inspect full account history and manage account status.</p></div><div className="rowactions"><button className="secondary" onClick={()=>downloadAdminCsv("users")}><Download size={16}/> Export CSV</button><button className="secondary" onClick={()=>openBalance()}><WalletCards size={16}/> Correct balance</button></div></div>\n  <div className="adminsearch"><Search size={17}/><input placeholder="Search name, email, phone or referral code" value={search} onChange={e=>setSearch(e.target.value)}/></div>\n  <div className="adminpanel balancehelp"><div><h3>Manual balance correction</h3><p className="muted">Use this only after verifying the member's payment or earnings. Every correction requires a reason and is added to the audit trail.</p></div><button className="secondary" onClick={()=>openBalance()}>Open tool</button></div>\n  <div className="adminpanel tablepanel"><div className="admintable"><div className="adminrow adminrowhead"><span>User</span><span>Phone</span><span>Package</span><span>Balance</span><span>Status</span><span>Action</span></div>{filtered.map(u=><div className="adminrow" key={u.id}><div><b>{u.name}</b><small>{u.email}</small><small>Ref: {u.referralCode}</small></div><span>{u.phone}</span><span>{u.package?.name||"—"}</span><span>{money(u.wallet?.balance)}</span><span><em className={`adminstatus ${u.status.toLowerCase()}`}>{u.status}</em></span><div className="rowactions"><button className="rowaction" onClick={()=>openDetails(u)}><Eye size={14}/> Details</button><button className="rowaction" onClick={()=>openBalance(u)}><WalletCards size={14}/> Balance</button><button className="rowaction" onClick={()=>action(()=>adminApi(`/admin/users/${u.id}/status`,{method:"PATCH",body:JSON.stringify({status:u.status==="ACTIVE"?"SUSPENDED":"ACTIVE"})}),u.status==="ACTIVE"?"User suspended":"User reactivated")}>{u.status==="ACTIVE"?<><Ban size={14}/> Suspend</>:<><UserCheck size={14}/> Activate</>}</button></div></div>)}{!filtered.length&&<div className="adminempty">No users match your search.</div>}</div></div>\n  {balanceOpen&&<div className="modalbackdrop" onClick={()=>setBalanceOpen(false)}><div className="modal adminbalance" onClick={e=>e.stopPropagation()}><div className="modalhead"><div><span className="pill">WALLET CORRECTION</span><h2>Update member balance</h2></div><button className="iconbtn" onClick={()=>setBalanceOpen(false)}><X size={20}/></button></div><form className="adminbalanceform" onSubmit={submit}><p className="muted">Enter the member's email address. For a missing commission, choose <b>Add to balance</b> and enter the verified amount.</p><label>Member email<input required type="email" placeholder="member@example.com" value={form.email} onChange={e=>setForm({...form,email:e.target.value})}/></label><label>Correction type<select value={form.mode} onChange={e=>setForm({...form,mode:e.target.value})}><option value="add">Add to balance</option><option value="subtract">Subtract from balance</option><option value="set">Set exact balance</option></select></label><label>Amount (KSh)<input required type="number" min="0" step="1" placeholder="e.g. 200" value={form.amount} onChange={e=>setForm({...form,amount:e.target.value})}/></label><label>Reason<input required maxLength="500" placeholder="Verified package commission missing" value={form.reason} onChange={e=>setForm({...form,reason:e.target.value})}/></label><label className="checkline"><input type="checkbox" checked={form.updateTotalEarned} onChange={e=>setForm({...form,updateTotalEarned:e.target.checked})}/> Also update Total Earned</label><p className="muted small">Only enable Total Earned when the correction represents genuine earnings that were missed. Pending balance is not changed.</p><div className="rowactions"><button type="button" className="secondary" onClick={()=>setBalanceOpen(false)}>Cancel</button><button type="submit" className="primary narrow">Apply correction</button></div></form></div></div>}\n  {detail&&<div className="modalbackdrop" onClick={()=>setDetail(null)}><div className="modal adminmemberdetail" onClick={e=>e.stopPropagation()}><div className="modalhead"><div><span className="pill">MEMBER PROFILE</span><h2>{detail.name}</h2><p className="muted">{detail.email} · {detail.phone}</p></div><button className="iconbtn" onClick={()=>setDetail(null)}><X size={20}/></button></div><div className="detailgrid"><div><span>Balance</span><b>{money(detail.wallet?.balance)}</b></div><div><span>Total earned</span><b>{money(detail.wallet?.totalEarned)}</b></div><div><span>Pending</span><b>{money(detail.wallet?.pendingBalance)}</b></div><div><span>Withdrawn</span><b>{money(detail.wallet?.totalWithdrawn)}</b></div><div><span>Package</span><b>{detail.package?.name||"None"}</b></div><div><span>Status</span><b>{detail.status}</b></div></div><div className="detailcols"><div><h3>Recent transactions</h3>{(detail.transactions||[]).slice(0,10).map(x=><div className="detailrow" key={x.id}><span>{x.type.replaceAll("_"," ")}<small>{x.reference}</small></span><b>{money(x.amount)} · {x.status}</b></div>)}{!detail.transactions?.length&&<p className="muted">No transactions.</p>}</div><div><h3>Referrals</h3>{(detail.referrals||[]).slice(0,10).map(x=><div className="detailrow" key={x.id}><span>{x.name}<small>{x.email}</small></span><b>{x.package?.name||"No package"}</b></div>)}{!detail.referrals?.length&&<p className="muted">No referrals.</p>}</div></div><div className="detailactions"><button className="secondary" onClick={()=>{setDetail(null);openBalance(detail)}}><WalletCards size={15}/> Correct balance</button></div></div></div>}\n  {detailsLoading&&<div className="detailloading">Loading member details…</div>}\n </section>\n}\n'''
s=s[:start]+users+s[end:]
# replace AdminTransactions with enhanced plus add new components before withdrawals
start=s.index('function AdminTransactions('); end=s.index('function AdminWithdrawals(',start)
tx='''function AdminTransactions({rows}){const [repair,setRepair]=useState(null);return <section className="adminsection"><div className="adminsectionhead"><div><h1>Transactions</h1><p className="muted">Package payments, commissions, refunds and withdrawal records.</p></div><div className="rowactions"><button className="secondary" onClick={()=>downloadAdminCsv("transactions")}><Download size={16}/> Export CSV</button><button className="secondary" onClick={()=>setRepair({email:"",reference:""})}><Wrench size={16}/> Repair payment</button></div></div><div className="adminpanel tablepanel"><div className="admintable"><div className="adminrow adminrowhead"><span>Reference</span><span>Member</span><span>Type</span><span>Amount</span><span>Status</span><span>Date</span></div>{rows.map(x=><div className="adminrow" key={x.id}><div><b>{x.reference}</b><small>{x.metadata?.paystack?.gateway_response||x.metadata?.paystack?.display_text||""}</small></div><div><b>{x.user?.name}</b><small>{x.user?.email}</small></div><span>{x.metadata?.adminBalanceAdjustment?"ADMIN BALANCE ADJUSTMENT":x.type.replaceAll("_"," ")}</span><strong className={x.metadata?.adminBalanceAdjustment?(Number(x.amount)>=0?"green":"adminnegative"):""}>{money(x.amount)}</strong><em className={`adminstatus ${String(x.status).toLowerCase()}`}>{x.status}</em><small>{new Date(x.createdAt).toLocaleString()}</small></div>)}{!rows.length&&<div className="adminempty">No transactions yet.</div>}</div></div>{repair&&<AdminPaymentRepairInline value={repair} onClose={()=>setRepair(null)}/>}</section>}\n\nfunction AdminPaymentRepair({action}){return <section className="adminsection"><div className="adminsectionhead"><div><span className="pill">PAYMENT RECOVERY</span><h1>Repair a verified payment</h1><p className="muted">Enter the member email and Paystack reference. NEXORA verifies the charge with Paystack before activating the package or restoring the missing record.</p></div></div><AdminPaymentRepairInline action={action}/></section>}\nfunction AdminPaymentRepairInline({value,onClose,action}){const [form,setForm]=useState(value||{email:"",reference:""}),[busy,setBusy]=useState(false),[result,setResult]=useState("");const submit=async e=>{e.preventDefault();setBusy(true);setResult("");try{const d=await adminApi("/admin/payments/repair",{method:"POST",body:JSON.stringify(form)});setResult(d.message||"Payment repair complete");if(action)await action(async()=>d,"Payment repair completed")}catch(e){setResult(e.message)}finally{setBusy(false)}};return <div className="adminpanel repairpanel"><form className="repairform" onSubmit={submit}><div className="repairintro"><CreditCard size={22}/><div><h3>Verify before crediting</h3><p className="muted small">This tool never trusts an email or reference alone. The backend checks Paystack and only repairs a successful charge.</p></div></div><label>Member email<input required type="email" placeholder="member@example.com" value={form.email} onChange={e=>setForm({...form,email:e.target.value})}/></label><label>Paystack transaction reference<input required placeholder="e.g. NEXORA-..." value={form.reference} onChange={e=>setForm({...form,reference:e.target.value})}/></label>{result&&<div className="notice">{result}</div>}<div className="rowactions"><button type="button" className="secondary" onClick={onClose}>Cancel</button><button className="primary" disabled={busy}>{busy?"Verifying…":"Verify & repair payment"}</button></div></form></div>}\n\n'''
s=s[:start]+tx+s[end:]
# Add activity before packages
marker='function AdminPackages('
activity='''function AdminActivity(){const [rows,setRows]=useState([]),[loading,setLoading]=useState(true),[err,setErr]=useState("");const load=async()=>{setLoading(true);try{setRows(await adminApi("/admin/activity"))}catch(e){setErr(e.message)}finally{setLoading(false)}};useEffect(()=>{load()},[]);return <section className="adminsection"><div className="adminsectionhead"><div><span className="pill">AUDIT TRAIL</span><h1>Admin activity</h1><p className="muted">A record of sensitive administrator actions.</p></div><button className="secondary" onClick={load}><RefreshCw size={16}/> Refresh</button></div>{err&&<div className="error">{err}</div>}<div className="adminpanel tablepanel"><div className="admintable"><div className="adminrow adminrowhead"><span>Action</span><span>Target</span><span>Admin</span><span>Details</span><span>Date</span><span>Reference</span></div>{loading?<div className="adminempty">Loading activity…</div>:rows.map(x=><div className="adminrow" key={x.id}><div><b>{String(x.action).replaceAll("_"," ")}</b></div><div><b>{x.targetType||"—"}</b><small>{x.targetEmail||x.targetId||""}</small></div><span>{x.adminEmail}</span><span>{x.details?.reason||x.details?.reference||x.details?.status||"—"}</span><small>{new Date(x.createdAt).toLocaleString()}</small><small>{x.details?.reference||"—"}</small></div>)}{!loading&&!rows.length&&<div className="adminempty">No admin activity recorded yet.</div>}</div></div></section>}\n'''
s=s.replace(marker,activity+marker,1)
# logo frontend auth and sidebar/header/dashboard
s=s.replace('<div className="brand">NEXORA<span>.</span></div><p className="muted">Connect. Grow. Earn.</p>', '<div className="memberbrand"><img src="/nexora-logo.png"/><div><div className="brand">NEXORA<span>.</span></div><p className="muted">Connect. Grow. Earn.</p></div></div>')
s=s.replace('<div className="app"><aside className={mobile?"open":""}><div className="brand">NEXORA<span>.</span></div>', '<div className="app"><aside className={mobile?"open":""}><div className="membernavbrand"><img src="/nexora-logo.png"/><div><b>NEXORA</b><small>MEMBER</small></div></div>')
s=s.replace('<div className="avatar">{me.user.name?.[0]?.toUpperCase()||"N"}</div>', '<div className="memberheaderbrand"><img src="/nexora-logo.png"/><div className="avatar">{me.user.name?.[0]?.toUpperCase()||"N"}</div></div>')
s=s.replace('<div className="heroicon"><ShieldCheck size={38}/></div>', '<div className="heroicon"><img src="/nexora-logo.png" alt="NEXORA"/></div>')
p.write_text(s)
print('frontend updated')
